const item = $input.item.json;
const recordId = item.id || '';
const rawUrl   = item['YouTube_Links'] || item['TikTok_Links'] || item['Instagram_Links'] || '';
function normalizeUrl(url) {
  let clean = url.split('?')[0].replace(/\/$/, '');
  clean = clean.replace('/reel/', '/reels/');
  return clean;
}
const url = normalizeUrl(rawUrl);
const getSS = (v) => (v && typeof v === 'object' ? v.name : v) || '';
const existing = {
  sourceName:    item['Source Name']          || '',
  platform:      item['Platform']             || '',
  category:      getSS(item['Category']),
  sourceType:    getSS(item['Source Type']),
  primaryFocus:  item['Primary Focus']        || '',
  igHandle:      item['Instagram_Handle']     || '',
  ttHandle:      item['TikTok_Handle']        || '',
  ytChannelId:   item['YouTube Channel ID']   || '',
  ytChannelName: item['YouTube Channel Name'] || '',
  status:        getSS(item['Status']),
};
let platform = '', identifier = '', identifierType = '';
if (url.includes('youtube.com') || url.includes('youtu.be')) {
  platform = 'YouTube';
  if (url.includes('/channel/'))  { identifier = url.split('/channel/')[1].split('/')[0].split('?')[0]; identifierType = 'channel_id'; }
  else if (url.includes('/@'))    { identifier = url.split('/@')[1].split('/')[0].split('?')[0]; identifierType = 'handle'; }
  else if (url.includes('/c/'))   { identifier = url.split('/c/')[1].split('/')[0]; identifierType = 'handle'; }
  else if (url.includes('/user/')){ identifier = url.split('/user/')[1].split('/')[0]; identifierType = 'handle'; }
} else if (url.includes('instagram.com') || url.includes('instagr.am')) {
  platform = 'Instagram';
  identifier = url.split('instagram.com/')[1]?.replace('@','').split('/')[0].split('?')[0] || '';
  identifierType = 'handle';
} else if (url.includes('tiktok.com')) {
  platform = 'TikTok';
  if (url.includes('/@')) { identifier = url.split('/@')[1].split('/')[0].split('?')[0]; }
  else { identifier = url.split('tiktok.com/')[1]?.replace('@','').split('/')[0] || ''; }
  identifierType = 'handle';
}
if (!platform || !identifier) return { json: { skip: true, recordId, reason: 'Cannot detect platform from: ' + url } };
return { json: { skip: false, recordId, platform, identifier, identifierType, url, existing } };

const item = $input.item.json;
const recordId = item.id || '';
const rawUrl   = item['Video_Links'] || '';
function normalizeUrl(url) {
  if (url.includes('youtube.com/watch')) return url.trim().replace(/\/+$/, '');
  let clean = url.split('?')[0].replace(/\/$/, '');
  clean = clean.replace('/reel/', '/reels/');
  return clean;
}
const url = normalizeUrl(rawUrl);
let platform = '', identifier = '', identifierType = '';
if (url.includes('youtube.com') || url.includes('youtu.be')) {
  platform = 'YouTube';
  if (rawUrl.includes('watch?v='))  { identifier = rawUrl.split('watch?v=')[1].split('&')[0]; identifierType = 'video'; }
  else if (url.includes('shorts/'))   { identifier = url.split('shorts/')[1].split('?')[0]; identifierType = 'video'; }
  else if (url.includes('youtu.be/')){ identifier = url.split('youtu.be/')[1].split('?')[0]; identifierType = 'video'; }
} else if (url.includes('instagram.com')) {
  platform = 'Instagram';
  const match = url.match(/\/(reels?|p|tv)\/([^/?]+)/);
  identifier = match ? match[2] : '';
  identifierType = 'post';
} else if (url.includes('tiktok.com')) {
  platform = 'TikTok';
  if (url.includes('/video/')) { identifier = url.split('/video/')[1].split('?')[0]; identifierType = 'video'; }
}
if (!platform || !identifier) return { json: { skip: true, recordId, reason: 'Cannot detect platform or video ID from: ' + url } };
return { json: { skip: false, recordId, platform, identifier, identifierType, url, rawUrl } };

const d = $input.item.json;
const { platform, identifier, identifierType } = d;
const SUPADATA_KEY = 'eyJ0eXAiOiJKV1QiLCJhbGciOiJIUzI1NiIsImtpZCI6IjEifQ.eyJpc3MiOiJuYWRsZXMiLCJpYXQiOiIxNzQxNjk3Mzg2IiwicHVycG9zZSI6ImFwaV9hdXRoZW50aWNhdGlvbiIsInN1YiI6IjJmNDc1Yzg0OTBjNzQ0ZGNhMTJjODA3MzY3YzEzNTg1In0.th5iol8OEe8_Wkda7ENeG2WX_W7BnohBfGDb0_2v2SI';
const YT_API_KEY   = 'AIzaSyCiu4jOmy7kvNLMU9KAFcHhIW8ZVfB4OkQ';
let metadata = {};
try {
  if (platform === 'YouTube') {
    if (identifierType === 'channel_id') {
      const res = await this.helpers.httpRequest({ method: 'GET', json: true,
        url: `https://www.googleapis.com/youtube/v3/channels?part=snippet&id=${identifier}&key=${YT_API_KEY}` });
      metadata = { channelId: identifier, channelTitle: res.items?.[0]?.snippet?.title || '', description: res.items?.[0]?.snippet?.description || '' };
    } else {
      const s = await this.helpers.httpRequest({ method: 'GET', json: true,
        url: `https://www.googleapis.com/youtube/v3/search?part=snippet&q=${encodeURIComponent(identifier)}&type=channel&key=${YT_API_KEY}` });
      const chId = s.items?.[0]?.snippet?.channelId || '';
      if (chId) {
        const c = await this.helpers.httpRequest({ method: 'GET', json: true,
          url: `https://www.googleapis.com/youtube/v3/channels?part=snippet&id=${chId}&key=${YT_API_KEY}` });
        metadata = { channelId: chId, channelTitle: c.items?.[0]?.snippet?.title || '', description: c.items?.[0]?.snippet?.description || '' };
      }
    }
  } else if (platform === 'Instagram') {
    const res = await this.helpers.httpRequest({ method: 'GET', json: true,
      url: `https://api.supadata.ai/v1/instagram/user?username=${encodeURIComponent(identifier)}`,
      headers: { 'x-api-key': SUPADATA_KEY } });
    metadata = res;
  } else if (platform === 'TikTok') {
    const res = await this.helpers.httpRequest({ method: 'GET', json: true,
      url: `https://api.supadata.ai/v1/tiktok/user?username=${encodeURIComponent(identifier)}`,
      headers: { 'x-api-key': SUPADATA_KEY } });
    metadata = res;
  }
} catch(e) { metadata = { error: e.message }; }
return { json: { ...d, metadata } };

const d = $input.item.json;
const { identifier } = d;
const YT_API_KEY = 'AIzaSyCiu4jOmy7kvNLMU9KAFcHhIW8ZVfB4OkQ';
let metadata = {};
let authorHandle = '';
try {
  const vRes = await this.helpers.httpRequest({ method: 'GET', json: true,
    url: `https://www.googleapis.com/youtube/v3/videos?part=snippet,statistics,contentDetails&id=${identifier}&key=${YT_API_KEY}` });

  // YouTube quota error comes back as 200 with an error object, or 403
  if (vRes.error) {
    const code = vRes.error.code || 0;
    const msg  = vRes.error.message || JSON.stringify(vRes.error);
    const isQuota = code === 403 || String(msg).toLowerCase().includes('quota');
    console.log('[WF00e 4b-yt] API error:', code, msg);
    return { json: { ...d, metadata: null, authorHandle: '', _error: isQuota ? 'rate_limit' : 'api_error', _errorMsg: msg } };
  }

  const v = vRes.items?.[0];
  if (!v) {
    return { json: { ...d, metadata: { title: d.rawUrl || d.url || '', error: 'not_found' }, authorHandle: '', _error: '' } };
  }

  const dur = v.contentDetails?.duration || 'PT0S';
  const m = dur.match(/PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/);
  const durationSeconds = m ? (parseInt(m[1]||0)*3600)+(parseInt(m[2]||0)*60)+parseInt(m[3]||0) : 0;
  authorHandle = v.snippet?.channelId || '';
  metadata = {
    title:          v.snippet?.title         || '',
    channelId:      v.snippet?.channelId     || '',
    channelTitle:   v.snippet?.channelTitle  || '',
    description:    v.snippet?.description   || '',
    publishedAt:    v.snippet?.publishedAt   || '',
    viewCount:      parseInt(v.statistics?.viewCount    || 0),
    likeCount:      parseInt(v.statistics?.likeCount    || 0),
    commentCount:   parseInt(v.statistics?.commentCount || 0),
    durationSeconds,
    tags: Array.isArray(v.snippet?.tags) ? v.snippet.tags.join(', ') : ''
  };
} catch(e) {
  console.log('[WF00e 4b-yt] exception:', e.message);
  return { json: { ...d, metadata: null, authorHandle: '', _error: 'api_error', _errorMsg: e.message } };
}
return { json: { ...d, metadata, authorHandle, _error: '' } };

const response = $input.item.json;
const d = $('3b. Parse Video Links URL').item.json;
const rawUrl = d.rawUrl || d.url || '';
const platform = d.platform || '';
let metadata = {};
let authorHandle = '';

if (platform === 'YouTube') {
  if (response._error) {
    return { json: { ...d, metadata: null, authorHandle: '', _error: response._error, _errorMsg: response._errorMsg || '' } };
  }
  metadata = response.metadata || {};
  authorHandle = response.authorHandle || '';
} else {
  const metaRes = response;
  console.log('[WF00e 4b] platform:', platform, '| keys:', Object.keys(metaRes || {}).join(', '));
  console.log('[WF00e 4b] full:', JSON.stringify(metaRes).substring(0, 2000));

  // Rate limit / API error guard
  const statusCode = metaRes.statusCode || metaRes.status || 0;
  const errorMsg = metaRes.error || metaRes.message || '';
  const isRateLimit = statusCode === 429 || String(errorMsg).toLowerCase().includes('rate limit') || String(errorMsg).toLowerCase().includes('quota') || String(errorMsg).toLowerCase().includes('limit exceeded');
  const isApiError = statusCode >= 400 || !!metaRes.error;

  if (isRateLimit) {
    console.log('[WF00e 4b] RATE LIMIT — aborting, will not create any records');
    return { json: { ...d, metadata: null, authorHandle: '', _error: 'rate_limit', _errorMsg: String(errorMsg) || 'Rate limit exceeded' } };
  }
  if (isApiError) {
    console.log('[WF00e 4b] API ERROR —', statusCode, errorMsg, '— aborting');
    return { json: { ...d, metadata: null, authorHandle: '', _error: 'api_error', _errorMsg: String(errorMsg) || String(statusCode) } };
  }

  const author = metaRes.author || {};
  authorHandle = author.username || author.uniqueId || author.handle || '';
  if (!authorHandle && rawUrl.includes('/@')) {
    authorHandle = rawUrl.split('/@')[1].split('/')[0].split('?')[0];
  }
  if (!authorHandle && platform === 'Instagram') {
    const parts = rawUrl.split('instagram.com/')[1] || '';
    const possible = parts.split('/')[0];
    if (possible && !['reel','reels','p','tv','stories','explore'].includes(possible)) authorHandle = possible;
  }

  const stats = metaRes.stats || {};
  console.log('[WF00e 4b] stats:', JSON.stringify(stats));
  const viewCount    = (stats.views    != null) ? parseInt(stats.views)    : 0;
  const likeCount    = (stats.likes    != null) ? parseInt(stats.likes)    : 0;
  const commentCount = (stats.comments != null) ? parseInt(stats.comments) : 0;

  const media = metaRes.media || {};
  const durationSeconds = (media.duration != null) ? parseInt(media.duration) : 0;
  const publishedAt = metaRes.createdAt || '';

  let tags = '';
  if (Array.isArray(metaRes.tags)) tags = metaRes.tags.join(', ');
  else if (metaRes.tags) tags = String(metaRes.tags);

  console.log('[WF00e 4b] PARSED — views:', viewCount, 'likes:', likeCount,
              'comments:', commentCount, 'duration:', durationSeconds,
              'handle:', authorHandle, 'title:', (metaRes.title||'').substring(0,80));

  metadata = {
    title:          metaRes.title || metaRes.description || '',
    description:    metaRes.description || '',
    authorHandle,
    channelTitle:   author.displayName || author.name || author.nickname || authorHandle || '',
    viewCount, likeCount, commentCount, durationSeconds, publishedAt, tags
  };
  if (!metadata.title) metadata.title = rawUrl;
}
return { json: { ...d, metadata, authorHandle, _error: '' } };

