parameters.jsCode:
const d = $input.item.json;
const { platform, identifier, url: rawUrl, metadata, authorHandle, recordId } = d;
const ctx = $('1d3. Pick First Video').first().json;
const cfg = ctx.cfg || {};
const BASE = cfg.video_base_id;
if (!BASE) { throw new Error('Client config missing: no video_base_id on the Video branch.'); }
const AT_PAT = 'REDACTED_AIRTABLE';

function normalizeUrl(u) {
  if (!u) return '';
  if (u.includes('youtube.com/watch')) return u.trim().replace(/\/+$/, '');
  let s = u.trim().replace(/\/+$/, '');
  s = s.replace(/instagram\.com\/reel\//, 'instagram.com/reels/');
  return s;
}

const url = normalizeUrl(rawUrl);
const item = ctx;
const existingSourceName  = item['Source Name']    || '';
const existingPlatform    = item['Platform']        || '';
const existingIgHandle    = item['Instagram_Handle']|| '';
const existingTtHandle    = item['TikTok_Handle']   || '';
const getSS = (v) => (v && typeof v === 'object') ? (v.name || '') : (v || '');
const existingCategory    = getSS(item['Category']);
const existingStatus      = getSS(item['Status']);
const existingSourceType  = getSS(item['Source Type']);
const alreadyProcessed    = !!item['Video_Links_Processed'];

let existingVLId = '', existingViralId = '', existingReelId = '';
try {
  if (identifier) {
    const f = encodeURIComponent(`{Video ID}="${identifier}"`);
    const r = await this.helpers.httpRequest({ method: 'GET', json: true,
      url: `https://api.airtable.com/v0/${BASE}/tblWBISPAy99YtoPw?filterByFormula=${f}`,
      headers: { Authorization: `Bearer ${AT_PAT}` } });
    if ((r.records||[]).length > 0) existingVLId = r.records[0].id;
  }
  const f2 = encodeURIComponent(`{URL}="${url}"`);
  const r2 = await this.helpers.httpRequest({ method: 'GET', json: true,
    url: `https://api.airtable.com/v0/${BASE}/tbl12IsF6vUdPY60r?filterByFormula=${f2}`,
    headers: { Authorization: `Bearer ${AT_PAT}` } });
  if ((r2.records||[]).length > 0) existingViralId = r2.records[0].id;
  const f3 = encodeURIComponent(`{Source URL}="${url}"`);
  const r3 = await this.helpers.httpRequest({ method: 'GET', json: true,
    url: `https://api.airtable.com/v0/${BASE}/tblSBKG2Zx2nZUPIT?filterByFormula=${f3}`,
    headers: { Authorization: `Bearer ${AT_PAT}` } });
  if ((r3.records||[]).length > 0) existingReelId = r3.records[0].id;
} catch(e) { console.log('Pre-check error:', e.message); }

const needsVideoLib   = !existingVLId;
const needsViralLib   = !existingViralId;
const needsReelEngine = !existingReelId;

const VALID_CATEGORIES = ['News', 'Education', 'Product'];
let inferredCategory = VALID_CATEGORIES.includes(existingCategory) ? existingCategory : '';
if (!inferredCategory) {
  const t = (metadata.title || metadata.description || '').toLowerCase();
  const edu = ['how to','full course','beginner','masterclass','tutorial','guide','explained','learn ','lessons','levels of',' tips','skills','stop using',"here's the fix",'step by step','complete guide','from scratch','for beginners','crash course','deep dive','walkthrough','how i use','how i build','setup'];
  const prod = ['product intro','product demo','product launch','product review','unboxing','hands on','first look'];
  if (edu.some(kw => t.includes(kw))) inferredCategory = 'Education';
  else if (prod.some(kw => t.includes(kw))) inferredCategory = 'Product';
  else inferredCategory = 'News';
}

let contentType = 'Video';
if (platform === 'TikTok')                                                   contentType = 'TikTok';
else if (platform === 'Instagram')                                           contentType = 'Reel';
else if (platform === 'YouTube' && (metadata.durationSeconds || 0) <= 60)   contentType = 'Short';

function toTitleCase(str) {
  if (!str) return '';
  let s = str.trim();
  if (!s.includes(' ')) s = s.replace(/([a-z])([A-Z])/g,'$1 $2').replace(/([a-zA-Z])([0-9])/g,'$1 $2');
  return s.toLowerCase().split(/\s+/).filter(w=>w.length>0).map(w=>w[0].toUpperCase()+w.slice(1)).join(' ');
}

const author       = metadata.author || metadata.creator || metadata.user || {};
const rawName      = metadata.channelTitle || author.name || author.displayName || author.nickname || metadata.full_name || metadata.name || '';
const sourceName   = existingSourceName || toTitleCase(rawName) || toTitleCase((authorHandle||'').replace(/^@/,'')) || '';
const channelId    = metadata.channelId || '';
const rawHandle    = authorHandle || metadata.uniqueId || metadata.username || author.username || metadata.owner?.username || '';
const creatorHandle = rawHandle ? '@' + rawHandle.replace(/^@/,'') : '';
const title        = (metadata.title || metadata.desc || metadata.description || url).substring(0,200);
let tags = '';
if (Array.isArray(metadata.tags))          tags = metadata.tags.join(', ');
else if (metadata.tags)                    tags = String(metadata.tags);
else if (Array.isArray(metadata.hashtags)) tags = metadata.hashtags.join(', ');

let publishedAt = metadata.publishedAt || metadata.published_at || '';
if (!publishedAt && metadata.createTime)         publishedAt = new Date(metadata.createTime * 1000).toISOString();
if (!publishedAt && metadata.timestamp)          publishedAt = new Date(metadata.timestamp * 1000).toISOString();
if (!publishedAt && metadata.taken_at_timestamp) publishedAt = new Date(metadata.taken_at_timestamp * 1000).toISOString();

const description  = (metadata.description || metadata.desc || metadata.caption || '').substring(0,5000);
const viewCount    = parseInt(metadata.viewCount    || metadata.playCount    || metadata.view_count    || metadata.video_view_count || 0);
const likeCount    = parseInt(metadata.likeCount    || metadata.like_count   || metadata.likes_count   || metadata.diggCount || 0);
const commentCount = parseInt(metadata.commentCount || metadata.comment_count|| metadata.comments_count|| 0);
const duration     = parseInt(metadata.durationSeconds || metadata.duration  || 0);

const platformBaseline = { YouTube: 5000, Instagram: 10000, TikTok: 50000 }[platform] || 5000;
const outlierScore = viewCount > 0 ? parseFloat((viewCount / platformBaseline).toFixed(2)) : 0;

const out = {
  recordId, platform, url, alreadyProcessed, cfg,
  existingSourceName, existingPlatform, existingCategory,
  existingIgHandle, existingTtHandle, existingStatus, existingSourceType,
  authorHandle, metadata, inferredCategory,
  needsVideoLib, needsViralLib, needsReelEngine,
  existingVLId, existingViralId, existingReelId,
  'Video ID':       identifier,
  'Title':          title,
  'URL':            url,
  'Platform':       platform,
  'Source Name':    sourceName,
  'Channel ID':     channelId,
  'Creator_Handle': creatorHandle,
  'Description':    description,
  'Tags':           tags,
  'Content Type':   contentType,
  'Status':         'Promoted',
  'Outlier Score':  outlierScore,
  'Associated_Sources': recordId ? [recordId] : [],
};
if (viewCount > 0)    out['View Count']    = viewCount;
if (likeCount > 0)    out['Like Count']    = likeCount;
if (commentCount > 0) out['Comment Count'] = commentCount;
if (duration > 0)     out['Duration']      = duration;
if (publishedAt)      out['Published At']  = publishedAt;
return { json: out };

const aiResponse = $input.item.json;
const d = $('3a. Parse Links URL').first().json;
const metadata = $('4a. Fetch Profile Metadata').first().json.metadata || {};
let ai = {};
try {
  let raw = aiResponse.choices[0].message.content || '';
  raw = raw.replace(/```json|```/g, '').trim();
  ai = JSON.parse(raw);
} catch(e) { ai = {}; }
function toTitleCase(str) {
  if (!str) return '';
  let s = str.trim();
  if (!s.includes(' ')) { s = s.replace(/([a-z])([A-Z])/g, '$1 $2').replace(/([a-zA-Z])([0-9])/g, '$1 $2'); }
  return s.toLowerCase().split(' ').filter(w => w.length > 0).map(w => w[0].toUpperCase() + w.slice(1)).join(' ');
}
function cleanHandle(h) { const raw = (h || '').replace(/^@/, '').trim(); return raw ? '@' + raw : ''; }
const ex = d.existing || {};
const update = { id: d.recordId };
if (!ex.sourceName) {
  const rawName = ai.source_name || metadata.channelTitle || metadata.full_name || metadata.name || metadata.nickname || metadata.display_name || metadata.displayName || '';
  update['Source Name'] = toTitleCase(rawName || d.identifier || '');
}
if (!ex.platform)     update['Platform']      = d.platform;
if (!ex.category)     update['Category']      = ai.category      || 'Other';
if (!ex.sourceType)   update['Source Type']   = ai.source_type   || d.platform;
if (!ex.primaryFocus) update['Primary Focus'] = ai.primary_focus || '';
if (!ex.status)       update['Status']        = 'Active';
update['Last Checked'] = new Date().toISOString();
if (d.platform === 'YouTube') {
  if (!ex.ytChannelId)   update['YouTube Channel ID']   = metadata.channelId || (d.identifierType === 'channel_id' ? d.identifier : '');
  if (!ex.ytChannelName) update['YouTube Channel Name'] = toTitleCase(metadata.channelTitle || ai.source_name || '');
}
if (d.platform === 'Instagram' && !ex.igHandle) {
  const h = cleanHandle(metadata.username || metadata.owner?.username || (d.identifierType === 'handle' ? d.identifier : '') || ai.instagram_handle || '');
  if (h) update['Instagram_Handle'] = h;
}
if (d.platform === 'TikTok' && !ex.ttHandle) {
  const h = cleanHandle(metadata.uniqueId || metadata.username || (d.identifierType === 'handle' ? d.identifier : '') || ai.tiktok_handle || '');
  if (h) update['TikTok_Handle'] = h;
}
if (!ex.ttHandle && ai.tiktok_handle)    update['TikTok_Handle']    = cleanHandle(ai.tiktok_handle);
if (!ex.igHandle && ai.instagram_handle) update['Instagram_Handle'] = cleanHandle(ai.instagram_handle);
return { json: update };

const d = $input.item.json;
const out = {
  'Video ID':       d['Video ID']       || '',
  'Title':          d['Title']          || '',
  'URL':            d['URL']            || '',
  'Platform':       d['Platform']       || '',
  'Source Name':    d['Source Name']    || '',
  'Channel ID':     d['Channel ID']     || '',
  'Creator_Handle': d['Creator_Handle'] || '',
  'Description':    d['Description']    || '',
  'Tags':           d['Tags']           || '',
  'Content Type':   d['Content Type']   || '',
  'Status':         'Promoted',
  'Outlier Score':  d['Outlier Score']  || 0,
  'Associated_Sources': d.recordId ? [d.recordId] : [],
};
if (d['View Count']    > 0) out['View Count']    = d['View Count'];
if (d['Like Count']    > 0) out['Like Count']    = d['Like Count'];
if (d['Comment Count'] > 0) out['Comment Count'] = d['Comment Count'];
if (d['Duration']      > 0) out['Duration']      = d['Duration'];
if (d['Published At'])      out['Published At']  = d['Published At'];
return { json: out };

const d = $('5b. Build Video Records').first().json;
